# What a picture draws its words in. The report carries them all.
PICTURE_FAMILIES = ("Zij Interface", "Zij Interface Marks", "DejaVu Sans")


def font_face_css(*families):
    """The @font-face rules of `families`, or of the whole set if none is named."""
    return "".join(
        f"@font-face{{font-family:'{family}';font-weight:{weight};font-style:normal;"
        + (f"unicode-range:{points};" if points else "")
        + f"src:url(data:font/woff2;base64,{payload}) format('woff2');}}"
        for family, weight, points, payload in _FACES if not families or family in families
    )
